grid = [[4]*13 for _ in range(20)]
points=[(1,2),(1,9),(6,11),(7,4),(12,2),(13,11),(17,4),(17,8)]
# source motif offsets centered at (12,7), including background 4 as blank and black 0
motif=[[4,5,5],[8,5,8],[8,5,0]]
# preserve special template; stamp motif centered on each singleton marker
for r,c in points:
    for dr in range(-1,2):
        for dc in range(-1,2):
            rr,cc=r+dr,c+dc
            if 0 <= rr < 20 and 0 <= cc < 13:
                grid[rr][cc]=motif[dr+1][dc+1]
# source pattern original
for dr in range(-1,2):
    for dc in range(-1,2):
        grid[12+dr][7+dc]=motif[dr+1][dc+1]
print('\n'.join(' '.join(map(str,row)) for row in grid))
